import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o,af as i}from"./chunks/mermaid.YsAH9es0.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const g=JSON.parse('{"title":"Claude Code Official Practices","description":"What the official Claude Code docs say about context files, subagents, hooks, permissions, sandbox defaults and review loops, with three team-level takeaways.","frontmatter":{"title":"Claude Code Official Practices","description":"What the official Claude Code docs say about context files, subagents, hooks, permissions, sandbox defaults and review loops, with three team-level takeaways.","domain":"product","tags":["coding-agent"],"role":"reference"},"headers":[],"relativePath":"products/claude/claude-code-official-practices.md","filePath":"products/claude/claude-code-official-practices.md","lastUpdated":1793277967000}'),s={name:"products/claude/claude-code-official-practices.md"};function n(d,e,r,l,c,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="claude-code-official-practices" tabindex="-1">Claude Code Official Practices <a class="header-anchor" href="#claude-code-official-practices" aria-label="Permalink to &quot;Claude Code Official Practices&quot;">​</a></h1><p><strong>Bottom line</strong>: The official docs separate deterministic mechanisms from probabilistic ones. Put what must always happen into hooks and startup-loaded instruction files. Move side work that would pollute the main conversation into subagents with their own context. Treat AI code review as triage with a built-in self-check, not as a gate that can sign off for a human.</p><blockquote><p><strong>Audience</strong>: engineers and tech leads adopting Claude Code in a team. <strong>Prerequisites</strong>: basic Claude Code usage. See <a href="./claude-code.html">Claude Code CLI</a> and the <a href="./claude-code-cookbook.html">Cookbook</a>. <strong>Non-goal</strong>: this page is not a feature reference. It covers only claims backed by quoted official text.</p></blockquote><p>Sources were fetched on 2026-10-21; the page list is at the end. Where the fetched text did not support a value, this page says so instead of guessing.</p><h2 id="context-files" tabindex="-1">Context files <a class="header-anchor" href="#context-files" aria-label="Permalink to &quot;Context files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>What the docs say</th></tr></thead><tbody><tr><td>Name and location</td><td>The project file is <code>CLAUDE.md</code>, at <code>./CLAUDE.md</code> or <code>./.claude/CLAUDE.md</code>. Either location works.</td></tr><tr><td>Local variant</td><td><code>CLAUDE.local.md</code> sits at the same level and loads together with <code>CLAUDE.md</code>.</td></tr><tr><td>Loading</td><td>Files at and above the working directory load at startup, so their cost is paid every session.</td></tr><tr><td>Guidance</td><td>More specific and concise instructions are followed more reliably.</td></tr></tbody></table><p>Not established by the fetched text: a per-file line limit, when subdirectory files load, and capacity thresholds for rules or auto memory.</p><h2 id="subagents-and-task-decomposition" tabindex="-1">Subagents and task decomposition <a class="header-anchor" href="#subagents-and-task-decomposition" aria-label="Permalink to &quot;Subagents and task decomposition&quot;">​</a></h2><ul><li>Each subagent runs in its own context window, with its own system prompt, restricted tool access and independent permissions.</li><li>Delegation is matched on the subagent&#39;s <code>description</code>. Writing the description is writing the routing condition.</li><li>Parallelism is not free: running several sessions or subagents multiplies token usage. Weigh that cost when deciding how many to run.</li></ul><p>Not established: where subagent files live, their precedence, and the allowed values of fields such as <code>model</code>.</p><h2 id="hooks-and-automation" tabindex="-1">Hooks and automation <a class="header-anchor" href="#hooks-and-automation" aria-label="Permalink to &quot;Hooks and automation&quot;">​</a></h2><ul><li>Hooks are user-defined shell commands that run at fixed points in the Claude Code lifecycle. They give deterministic control: an action always happens instead of depending on the model.</li><li>Documented uses: enforcing project rules, automating repetitive tasks and integrating existing tools.</li><li>When a hook blocks an edit, Claude receives an explanation of why and adjusts. Write the block message with the same care as the block itself.</li></ul><p>Not established: the full event list, JSON input and output shapes, and exit-code semantics per event.</p><h2 id="permissions-and-sandbox-defaults" tabindex="-1">Permissions and sandbox defaults <a class="header-anchor" href="#permissions-and-sandbox-defaults" aria-label="Permalink to &quot;Permissions and sandbox defaults&quot;">​</a></h2><ul><li>Interactive terminal and VS Code sessions start in Auto mode by default.</li><li>Manual mode starts read-only.</li><li>The built-in Bash sandbox is <strong>off</strong> by default.</li></ul><p>Read together: the default mode leans automatic, and the sandbox is not on by default. A team that wants a stricter baseline has to configure it explicitly.</p><h2 id="review-and-verification-loops" tabindex="-1">Review and verification loops <a class="header-anchor" href="#review-and-verification-loops" aria-label="Permalink to &quot;Review and verification loops&quot;">​</a></h2><ul><li>Code Review evaluates changes, then runs a separate verification step that checks each candidate finding against the code before reporting it. Findings appear as inline comments.</li><li>The docs state that the AI reviewer can miss bugs and security issues. Use it to route attention, not as a correctness guarantee before merge.</li></ul><h2 id="three-practices-to-adopt" tabindex="-1">Three practices to adopt <a class="header-anchor" href="#three-practices-to-adopt" aria-label="Permalink to &quot;Three practices to adopt&quot;">​</a></h2><ol><li><strong>Keep repository knowledge in the context file, and keep it specific.</strong> Put build, test and layout conventions in <code>./CLAUDE.md</code> or <code>./.claude/CLAUDE.md</code>. Delete slogan-style lines such as &quot;write clean code&quot;. Basis: the location rule and the specificity guidance above.</li><li><strong>Send exploratory work to subagents.</strong> Anything that dumps search results, logs or file contents into the main thread and is not read again belongs in a subagent. Put the trigger in its <code>description</code>, and size concurrency against the token multiplier. Basis: isolated context, description matching, parallel cost.</li><li><strong>Put &quot;must happen every time&quot; in hooks, not in instructions.</strong> Formatting and blocking out-of-scope edits are deterministic jobs. Instruction compliance is probabilistic; hook execution is not. Basis: deterministic control, rule enforcement, block feedback.</li></ol><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><ul><li>Assuming the sandbox is on. It is off by default.</li><li>Treating a long <code>CLAUDE.md</code> as free. It loads every session.</li><li>Treating a passing AI review as approval.</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>Compare these defaults with your team&#39;s actual <code>settings.json</code> in the <a href="./claude-code-cheatsheet.html">Cheatsheet</a>.</li><li>Apply the verify-yourself pattern in <a href="./claude-code-cookbook.html">Practical Workflows</a>.</li></ul><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><p>Fetched 2026-10-21:</p><ul><li><a href="https://code.claude.com/docs/en/memory" target="_blank" rel="noreferrer">https://code.claude.com/docs/en/memory</a></li><li><a href="https://code.claude.com/docs/en/sub-agents" target="_blank" rel="noreferrer">https://code.claude.com/docs/en/sub-agents</a></li><li><a href="https://code.claude.com/docs/en/agents" target="_blank" rel="noreferrer">https://code.claude.com/docs/en/agents</a></li><li><a href="https://code.claude.com/docs/en/hooks-guide" target="_blank" rel="noreferrer">https://code.claude.com/docs/en/hooks-guide</a></li><li><a href="https://code.claude.com/docs/en/security" target="_blank" rel="noreferrer">https://code.claude.com/docs/en/security</a></li><li><a href="https://code.claude.com/docs/en/sandboxing" target="_blank" rel="noreferrer">https://code.claude.com/docs/en/sandboxing</a></li><li><a href="https://code.claude.com/docs/en/code-review" target="_blank" rel="noreferrer">https://code.claude.com/docs/en/code-review</a></li></ul><p>Not used: an <code>anthropic.com/engineering</code> context-engineering article returned HTTP 404 on fetch.</p>',28)])])}const b=t(s,[["render",n]]);export{g as __pageData,b as default};
